function placeSupport(){
 const area=$('#support-area');if(!area)return;
 const workspace=area.closest('.workspace');if(!workspace)return;
 const narrow=matchMedia('(max-width:1100px)').matches;
 const anchor=scene==='mission'?$('#task-content .task-question'):scene==='exam'?$('.exam .task-prompt'):null;
 if(!anchor)return;
 const destination=narrow?anchor.parentElement:workspace;
 if(area.parentElement===destination)return;
 const focus=document.activeElement,restore=area.contains(focus);
 if(narrow)anchor.after(area);else workspace.append(area);
 if(restore)focus.focus({preventScroll:true});
}
matchMedia('(max-width:1100px)').addEventListener('change',placeSupport);

