/* Cada quadro visual está associado à sua altura; pausas não avançam a contagem. */
function stopAnimation(){clearTimeout(animationTimer);animationTimer=null;animation=null;piano?.mark(-1);}
function animationFrames(kind,pair){const a=Music.parse(pair[0]),b=Music.parse(pair[1]),r=Music.analyze(a,b);if(kind==='names')return r.counted.map((name,i)=>({m:Music.midi(Music.note(Music.letters[(Music.letters.indexOf(a.letter)+i)%7],i===0?a.alteration:i===r.number-1?b.alteration:0,a.octave+Math.floor((Music.letters.indexOf(a.letter)+i)/7))),text:`NOMES: ${i+1}/${r.number} — ${r.counted.slice(0,i+1).join(' → ')}. A origem conta como 1. Esta é a contagem diatônica, não a distância em semitons.`}));if(kind==='chromatic')return Array.from({length:r.semitones+1},(_,i)=>({m:Music.midi(a)+i,text:`DISTÂNCIA: ${i} de ${r.semitones} semitons percorridos. ${i===0?'Origem = zero passos.':'Cada altura vizinha soma um passo.'} Os ${r.number} nomes são outra contagem.`}));if(kind==='enharmonic')return [{pair:['C4','F#4'],text:'Dó → ré → mi → fá: 4 nomes. Dó–fá♯ = 6 semitons = quarta aumentada.'},{pair:['C4','Gb4'],text:'Dó → ré → mi → fá → sol: 5 nomes. Dó–sol♭ = 6 semitons = quinta diminuta. Mesma tecla, outra grafia.'}];return [{pair:['C4','F4'],text:'5 semitons: dó–fá = quarta justa (4 nomes).'}, {pair:['C4','F#4'],text:'6 semitons: dó–fá♯ = quarta aumentada (4 nomes).'}, {pair:['C4','Gb4'],text:'6 semitons: dó–sol♭ = quinta diminuta (5 nomes).'}, {pair:['C4','G4'],text:'7 semitons: dó–sol = quinta justa (5 nomes).'}];}
function startAnimation(kind,pair=Missions[mission].example){stopAnimation();piano.setPair(pair);piano.host.scrollIntoView({block:'start',behavior:'auto'});animation={kind,pair,frames:animationFrames(kind,pair),index:0,paused:prefs().reduced};animationStep();}
function animationStep(){if(!animation||!$('#animation-output'))return;clearTimeout(animationTimer);const frame=animation.frames[animation.index];if(frame.pair){piano.setPair(frame.pair);Sound.play(piano.notes.map(Music.midi),true);}else{piano.mark(frame.m);Sound.play([frame.m],false,.35);}$('#animation-output').textContent=frame.text+(prefs().reduced?' Movimento reduzido: usem Avançar um passo.':'');if(animation.index<animation.frames.length-1&&!animation.paused)animationTimer=setTimeout(()=>{animation.index++;animationStep();},frame.pair?1900:1050);else if(animation.index===animation.frames.length-1)$('#animation-output').textContent+=' Demonstração concluída. Vocês podem repetir.';}
function bindAudio(){if(!$('#voice'))return;populateVoices();$('#narration').onchange=e=>{prefs().narration=e.target.checked;Sound.setEnabled(e.target.checked);Progress.save();if(e.target.checked&&!('speechSynthesis'in window))notify('Narração indisponível; use as legendas.');};$('#voice').onchange=e=>{prefs().voice=e.target.value;Sound.setVoice(e.target.value);Progress.save();};$('#volume').oninput=e=>{prefs().volume=+e.target.value;Sound.setVolume(prefs().volume);Progress.save();};}
