function getExam(variant){const set=ExamSets[variant%2];return set.map((q,i)=>{const offset=(variant+i)%5;return {...q,pianoSupport:[false,true,false,true,true,true,true,false][i],options:q.options.map((_,j)=>q.options[(j+offset)%5]),reasons:q.reasons.map((_,j)=>q.reasons[(j+offset)%5]),correct:(q.correct-offset+5)%5};});}
