function composer(){composePair=(state().journey.composePair||[]).filter(i=>i>=0&&i<state().composition.length);mount(`<nav class="breadcrumb"><button data-action="return-final">← Missão 6</button><span>MESA DE COMPOSIÇÃO</span></nav><section class="mission-intro"><span class="eyebrow">AUTORIA DO NONO ANO</span><h1>Uma ideia, quatro a oito notas.</h1><p>Ativem “Gravar notas” e toquem o piano para construir uma sequência. Desativem a gravação para experimentar sem acrescentar notas. Os botões de cada nota permitem escolher pares ordenados para análise.</p>${characters('Uma repetição, um salto, uma aproximação… cada relação pode sugerir uma sensação.','Que relações entre os sons vocês escolheram e o que desejam expressar?')}</section><section class="panel"><div class="button-row"><button id="record-toggle" data-action="record-toggle" aria-pressed="false">○ Gravar notas: desligado</button><button data-action="play-composition">▶ Reproduzir sequência</button><button data-action="undo-note">Remover última nota</button><button data-action="clear-composition">Limpar sequência</button></div><div class="resources"><span class="eyebrow">RECURSOS LIBERADOS PELAS CONQUISTAS</span><p class="small">Acrescentem um par como ponto de partida e transformem a ideia com outras notas.</p>${Missions.map((m,i)=>'<button data-resource="'+i+'" '+(state().completed.includes(i)||prefs().teacher?'':'disabled')+'>'+m.achievement+'</button>').join('')}</div><div id="sequence" class="sequence"></div><p id="composition-pair" role="status">Selecione dois botões da sequência para analisar um par, na ordem origem → destino.</p><div id="composition-analysis"></div></section><section class="piano-panel" id="piano-host"></section><section class="panel"><label class="lead" for="reflection">Nono ano, que relações entre os sons vocês escolheram e o que desejam expressar?</label><textarea id="reflection" rows="4" maxlength="3000">${esc(state().reflection)}</textarea><div class="button-row"><button class="primary" data-action="save-composition">Salvar criação no dispositivo</button><button data-action="export">Exportar JSON</button><label class="file-button">Importar JSON<input id="import-json" type="file" accept=".json,application/json"></label></div><p class="small">A composição salva fica disponível aqui ao reabrir o projeto. O JSON contém notas com nome diatônico, alteração e oitava, além da reflexão. Importe apenas criações deste formato.</p><p id="composition-status" role="status"></p></section>${audioControls()}`,'composer');attachPiano('composer',true,'sharp',n=>{if(composerMode){if(state().composition.length>=8){notify('A sequência já tem oito notas. Removam uma para experimentar outra escolha.');return;}state().composition.push({...n});saveComposerDraft();renderSequence();}});renderSequence();$('#reflection').oninput=saveComposerDraft;$('#import-json').onchange=importCreation;}
